{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "TodoWrite",
    "description": "Your task queue: the durable list of everything the user has asked for, across all your parallel streams of work.\n\nWhen to use:\n- The moment a request arrives, record it as a todo before dispatching or starting it.\n- Update statuses in real time: in_progress when its work starts, completed the moment its result is delivered to the user, cancelled when the user drops it or changes their mind.\n- On every wake (a user message or a finished background task), reconcile the list first: what's running, what landed, what to dispatch next.\n\nStates and parallelism:\n- pending: not yet started. in_progress: actively being worked, by you or a background worker. completed: result delivered to the user. cancelled: no longer needed.\n- SEVERAL todos are normally in_progress at once — one per independent stream running in parallel (each dispatched worker, plus at most one thing you are doing inline). Never serialize independent streams just to keep a single one in_progress.\n- Keep the list current rather than perfect: cancel stale items instead of leaving them pending, and prune long-finished ones when the list gets noisy.\n\nSkip it for purely conversational replies and trivial one-step lookups you answer inline immediately.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "todos": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "string",
                "description": "Unique identifier for the TODO item"
              },
              "content": {
                "type": "string",
                "description": "The description/content of the todo item"
              },
              "status": {
                "type": "string",
                "enum": [
                  "pending",
                  "in_progress",
                  "completed",
                  "cancelled"
                ],
                "description": "The current status of the TODO item"
              }
            },
            "required": [
              "id",
              "content",
              "status"
            ]
          },
          "minItems": 2,
          "description": "Array of TODO items to update or create"
        },
        "merge": {
          "type": "boolean",
          "description": "Whether to merge the todos with the existing todos. If true, the todos will be merged into the existing todos based on the id field. You can leave unchanged properties undefined. If false, the new todos will replace the existing todos."
        }
      },
      "required": [
        "todos",
        "merge"
      ]
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "Task",
    "description": "Launch a new agent to handle complex, multi-step tasks autonomously.\n\nThe Task tool launches specialized subagents (subprocesses) that autonomously handle complex tasks. Each subagent_type has specific capabilities and tools available to it.\n\nWhen using the Task tool, you must specify a subagent_type parameter to select which agent type to use.\n\nWhen NOT to use the Task tool:\n- Simple, single or few-step tasks that can be performed by a single agent (using parallel or sequential tool calls) -- just call the tools directly instead.\n- For example:\n  - If you want to read a specific file path, use the Read tool instead of the Task tool, to find the match more quickly\n  - If you are searching for code within a specific file or set of 2-3 files, use the Read tool instead of the Task tool, to find the match more quickly\n\nUsage notes:\n- Always include a short description (3-5 words) summarizing what the agent will do\n- Launch multiple agents concurrently whenever possible, to maximize performance; to do that, use a single message with multiple tool uses.\n- When the agent is done, it will return a single message back to you. Specify exactly what information the agent should return back in its final response to you. Background subagent completion messages already include a user-visible summary portion; do not summarize or restate a single background subagent's result by default. Respond only when the user asks, multiple background subagents need synthesis, or the background subagent reports a blocker requiring parent action outside of the user-visible high level summary.\n- Agents can be resumed using the `resume` parameter by passing the agent ID from a previous invocation. This sends a follow-up message after the agent has completed, preserving existing context. If the agent is still running, the request fails; wait for completion before resuming. When NOT resuming, each invocation starts fresh and you should provide a detailed task description with all necessary context.\n- When using the Task tool, the subagent invocation does not have access to the user's message or prior assistant steps. Therefore, you should provide a highly detailed task description with all necessary context for the agent to perform its task autonomously.\n- The subagent's outputs should generally be trusted\n- Clearly tell the subagent which tasks you want it to perform, since it is not aware of the user's intent or your prior assistant steps (tool calls, thinking, or messages).\n- If the subagent description mentions that it should be used proactively, then you should try your best to use it without the user having to ask for it first. Use your judgement.\n- If the user specifies that they want you to run subagents \"in parallel\", you MUST send a single message with multiple Task tool use content blocks. For example, if you need to launch both a code-reviewer subagent and a test-runner subagent in parallel, send a single message with both tool calls.\n- Avoid delegating the full query to the Task tool and returning the result. In these cases, you should address the query using the other tools available to you.\n\nAvailable subagent_types and descriptions are listed in <available_subagent_types> in the initial user-info message at the start of this conversation.\n\nAvailable model slugs for subagents are listed in <available_subagent_models> in the initial user-info message at the start of this conversation.\n\nWhen an agent runs in the background, you will be automatically notified when it completes after you end your own turn - do NOT AwaitExternalShell, poll, or proactively check on its progress. Continue with other work or end your turn instead.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "description": {
          "type": "string",
          "description": "A short, user-friendly title for the subagent. This appears in the UI as the subagent's name. Make it concrete and distinct, consider recent titles to avoid reuse. For resumed subagents which you are prompting to work on a separate task, give an updated description based on the latest work the subagent is performing. (Do not rename if the subagent is continuing work on the same high-level task.)"
        },
        "prompt": {
          "type": "string",
          "description": "The task for the agent to perform"
        },
        "model": {
          "type": "string",
          "description": "Optional model slug for this agent. If provided, it must resolve to one of the available model slugs. If omitted, the subagent uses the same model as the parent agent. Do not pass if resume field is set (prior model will be used). Only choose an explicit model when the user directly requests it."
        },
        "resume": {
          "type": "string",
          "description": "Optional agent ID to resume from. If provided, sends a follow-up message to the agent after it has completed. Requests to a currently running asynchronous agent fail; wait for completion before resuming."
        },
        "subagent_type": {
          "type": "string",
          "enum": [
            "executor",
            "videoReview",
            "watchVideo",
            "computerUse",
            "browserUse"
          ],
          "description": "Subagent type to use for this task. Must be one of: executor, videoReview, watchVideo, computerUse, browserUse."
        },
        "file_attachments": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Optional array of file paths to images or videos to pass to video-review subagents. Files are read and attached to the subagent's context. Use to forward relevant media (e.g. images sent by user) to subagents."
        },
        "run_in_background": {
          "type": "boolean",
          "description": "Run the agent in the background (returns output_file path to check later). If this is false, you will be blocked until the agent completes. When true, the background subagent will send a notification when it completes. That notification includes a user-visible summary portion; do not summarize or restate a completed background subagent's result unless the user asks, multiple background subagents need synthesis, or a background subagent reports a blocker requiring parent action outside of the user-visible high level summary."
        }
      },
      "required": [
        "description",
        "prompt"
      ]
    }
  }
}

{
  "mode": "namespace",
  "namespace": "user-Aws-mcp",
  "namespaceStatus": "ready",
  "tools": [
    {
      "tool": "aws___call_aws",
      "description": "DEPRECATED: This tool is being deprecated in favor of `run_script`. Use `run_script` instead. Execute AWS CLI commands. PRIMARY tool when you know the exact command needed. - Command MUST start with \"aws\" and follow AWS CLI syntax - For cross-region operations, include --region; for alternate profiles, include --profile - max_results defaults to 100 for paginated operations. Larger values consume more tokens. OMIT for non-paginated ops (get, create, delete). PAGINATION: If response has non-null \"pagination_token\", results are INCOMPLETE. Call again with \"--starting-token <value>\". ALWAYS paginate through ALL pages before reporting counts or conclusions. MULTI-STEP PATTERNS: Most tasks require list→describe workflows. List operations return only identifiers—always follow with describe/get calls for full details. Never infer from names alone; retrieve and inspect actual data. MULTI-REGION/PROFILE: When a task involves \"all regions\" or multiple profiles, query EVERY relevant region/profile separately. LOCAL FILE SYSTEM: No filesystem access. Use '-' for output file args. No 'file://'/'fileb://'—provide values inline. S3-to-S3 operations (both source and destination are S3 URIs) ARE supported. Command restrictions: NO pipes, shell operators, grep/awk/sed, redirection, command substitution, shell variables, or local file paths. BACKGROUND TASKS: Long-running operations return {task_id, status:\"working\"}. Poll via `get_tasks` tool with task_ids=[...]—NOT an aws subcommand. Each task runs once. FILE UPLOAD: Ask user for a staging bucket. Get pre-signed URL via get_presigned_url, upload file, then call call_aws with staging_sources (bucket, key, cli_argument, optional extract). Do NOT include cli_argument flags in cli_command. For directories: zip first (zip-only, max 4GB), use extract:true. For commands with native S3 args (--code S3Bucket=X,S3Key=Y), use those directly—no staging needed. Examples: - aws s3api put-object --bucket my-bucket --key data.bin with staging_sources=[{\"bucket\":\"staging\",\"key\":\"data.bin\",\"cli_argument\":\"--body\"}] - aws lambda create-function --function-name F --runtime python3.12 --handler index.handler --role <arn> with staging_sources=[{\"bucket\":\"staging\",\"key\":\"func.zip\",\"cli_argument\":\"--zip-file\"}]",
      "inputSchema": {
        "type": "object",
        "properties": {
          "cli_command": {
            "description": "Complete AWS CLI command. MUST start with \"aws\"",
            "type": "string"
          },
          "max_results": {
            "default": 100,
            "description": "Max items for paginated operations. Defaults to 100. If response has non-null pagination_token, use --starting-token for more.",
            "type": "integer"
          },
          "staging_sources": {
            "anyOf": [
              {
                "anyOf": [
                  {
                    "items": {
                      "description": "Reference to a file previously uploaded to S3 via get_presigned_url.",
                      "properties": {
                        "bucket": {
                          "type": "string"
                        },
                        "key": {
                          "type": "string"
                        },
                        "cli_argument": {
                          "type": "string"
                        },
                        "extract": {
                          "default": false,
                          "type": "boolean"
                        }
                      },
                      "required": [
                        "bucket",
                        "key",
                        "cli_argument"
                      ],
                      "type": "object"
                    },
                    "type": "array"
                  },
                  {
                    "type": "null"
                  }
                ],
                "description": "Use ONLY when CLI needs a LOCAL file/dir input (`--body`, `--zip-file`, `--template-body`, `--policy-document`, `--cli-input-json` from file, `deploy push --source`, `gamelift upload-build --build-root`).\n\nSKIP if data already in S3 and CLI accepts S3 natively (`--s3-bucket/--s3-key`, `--code S3Bucket=,S3Key=`, `--s3-location`, `--revision s3Location={bucket=,key=,...}`).\n\nSteps: get_presigned_url(operation=\"upload\") → HTTP PUT → call this tool with cli_command FULLY OMITTING the file flag (no dangling `--zip-file`/`--body`/`--source`) plus `staging_sources` (≤25): [{\"bucket\":\"<bucket>\",\"key\":\"<key>\",\"cli_argument\":\"--zip-file\",\"extract\":false}]. `extract:true` for dirs (.zip only, ≤4GB). When CLI needs local file: 1) ask user for bucket 2) get_presigned_url(upload) 3) HTTP PUT 4) call_aws + staging_sources (OMIT file arg from cli_command)."
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "cli_command"
        ],
        "additionalProperties": false
      }
    },
    {
      "tool": "aws___get_presigned_url",
      "description": "Generate pre-signed S3 URLs for uploading or downloading files. Use BEFORE call_aws when a command requires a local file path. Use for direct S3 uploads/downloads instead of call_aws. Max upload 5 GB; larger files use multipart via call_aws. For uploads: generates PUT URL. For downloads: generates GET URL. No special headers needed unless s3_params provided—then corresponding HTTP headers MUST be included or request fails with SignatureDoesNotMatch.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "requests": {
            "description": "Array of 1-25 presigned URL requests.",
            "items": {
              "description": "A single presigned URL request.",
              "properties": {
                "operation": {
                  "description": "PUT (upload) or GET (download).",
                  "enum": [
                    "upload",
                    "download"
                  ],
                  "type": "string"
                },
                "bucket": {
                  "description": "S3 bucket name.",
                  "type": "string"
                },
                "key": {
                  "description": "S3 object key.",
                  "type": "string"
                },
                "region": {
                  "anyOf": [
                    {
                      "type": "string"
                    },
                    {
                      "type": "null"
                    }
                  ],
                  "description": "Override region. Falls back to session region."
                },
                "expires_in": {
                  "default": 900,
                  "description": "URL expiration in seconds (1–900). Above 900 → S3 rejects with 403.",
                  "maximum": 900,
                  "minimum": 1,
                  "type": "integer"
                },
                "s3_params": {
                  "anyOf": [
                    {
                      "additionalProperties": {
                        "type": "string"
                      },
                      "type": "object"
                    },
                    {
                      "type": "null"
                    }
                  ],
                  "description": "Extra S3 parameters to sign (e.g. ContentType). Corresponding headers MUST be included."
                }
              },
              "required": [
                "operation",
                "bucket",
                "key"
              ],
              "type": "object"
            },
            "type": "array"
          }
        },
        "required": [
          "requests"
        ],
        "additionalProperties": false
      }
    },
