    if ($r.NatGatewayId) {
      $natRoutes += [ordered]@{ rtb=$rt.RouteTableId; vpc=$rt.VpcId; name=$name; dest=$r.DestinationCidrBlock; nat=$r.NatGatewayId; state=$r.State }
    }
  }
}
$natRoutes | ConvertTo-Json | Set-Content "$dir\nat-routes.json"
Write-Output "NAT routes:"
$natRoutes | Format-Table -AutoSize | Out-String

