success.command:
$dir = "$env:TEMP\netaws-audit"
# Route tables: which point at NAT gateways
aws ec2 describe-route-tables --profile netaws --region us-west-2 --output json > "$dir\routes.json"
$rts = (Get-Content "$dir\routes.json" -Raw | ConvertFrom-Json).RouteTables
$natRoutes = @()
foreach ($rt in $rts) {
  $name = ($rt.Tags | Where-Object { $_.Key -eq 'Name' } | Select-Object -First 1).Value
  foreach ($r in $rt.Routes) {
    if ($r.NatGatewayId) {
      $natRoutes += [ordered]@{ rtb=$rt.RouteTableId; vpc=$rt.VpcId; name=$name; dest=$r.DestinationCidrBlock; nat=$r.NatGatewayId; state=$r.State }
    }
  }
}
$natRoutes | ConvertTo-Json | Set-Content "$dir\nat-routes.json"
Write-Output "NAT routes:"
$natRoutes | Format-Table -AutoSize | Out-String

# Cost Explorer last 30d network-ish usage types
$ce = aws ce get-cost-and-usage --time-period Start=2026-07-22,End=2026-08-21 --granularity MONTHLY --metrics UnblendedCost --group-by Type=DIMENSION,Key=USAGE_TYPE --filter '{\"Dimensions\":{\"Key\":\"SERVICE\",\"Values\":[\"EC2 - Other\",\"Amazon Elastic Load Balancing\",\"Amazon Virtual Private Cloud\",\"AWS Transit Gateway\",\"Amazon Route 53\",\"EC2-ELB\"]}}' --profile netaws --region us-east-1 --output json 2>&1
if ($LASTEXITCODE -ne 0) {
  Write-Output "CE_FILTER_FAILED"
  Write-Output $ce
  $ce = aws ce get-cost-and-usage --time-period Start=2026-07-22,End=2026-08-21 --granularity MONTHLY --metrics UnblendedCost --group-by Type=DIMENSION,Key=USAGE_TYPE --profile netaws --region us-east-1 --output json 2>&1
}
$ce | Set-Content "$dir\ce-raw.json"
Write-Output "CE exit $LASTEXITCODE len=$((Get-Item $dir\ce-raw.json).Length)"
